INSERT INTO `p5_projects` (`id`, `school_id`, `classroom_id`, `academic_year_id`, `theme`, `title`, `description`, `coordinator_name`, `target_dimensions`, `created_at`, `updated_at`) VALUES (1, 1, 1, 2, 'Aku cinta Indonesia', 'Aku Cinta Indonesia: Mengenal Ragam Budaya Daerah dan Adab Pelajar Muslim', 'Peserta didik mengamati keanekaragaman budaya daerah, mempraktikkan sikap tolong-menolong, dan menginternalisasi adab sopan santun islami.', 'Ranti Saputri, S.TP', '["Beriman, Bertakwa Kepada Tuhan YME, dan Berakhlak Mulia","Berkebhinekaan Global","Bergotong-Royong","Mandiri","Bernalar Kritis","Kreatif"]', NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`='Aku Cinta Indonesia: Mengenal Ragam Budaya Daerah dan Adab Pelajar Muslim', `coordinator_name`='Ranti Saputri, S.TP';
INSERT INTO `p5_projects` (`id`, `school_id`, `classroom_id`, `academic_year_id`, `theme`, `title`, `description`, `coordinator_name`, `target_dimensions`, `created_at`, `updated_at`) VALUES (2, 1, 1, 2, 'Gaya Hidup Berkelanjutan', 'Sampahku Tanggung Jawabku: Belajar Memilah Sampah dan Menjaga Kebersihan Lingkungan Sekolah', 'Peserta didik mempraktikkan pembiasaan hidup bersih, memilah sampah organik dan anorganik, serta menjaga kelestarian lingkungan sekolah sebagai wujud keimanan.', 'Nur Amalia, S.Pd., Gr', '["Beriman, Bertakwa Kepada Tuhan YME, dan Berakhlak Mulia","Gotong Royong","Bernalar Kritis","Mandiri"]', NOW(), NOW()) ON DUPLICATE KEY UPDATE `title`='Sampahku Tanggung Jawabku: Belajar Memilah Sampah dan Menjaga Kebersihan Lingkungan Sekolah', `coordinator_name`='Nur Amalia, S.Pd., Gr';
